SELECT * FROM pwodwi;
SELECT non, pri FROM pwodwi;
SELECT non AS non_pwodwi, pri AS pri_gdes FROM pwodwi;

SELECT * FROM pwodwi WHERE pri < 1000;
SELECT non FROM kliyan WHERE vil = 'Potoprens';
SELECT * FROM pwodwi WHERE pri BETWEEN 500 AND 2000 AND stok > 0;

SELECT * FROM pwodwi ORDER BY pri DESC LIMIT 5;
SELECT DISTINCT vil FROM kliyan;
SELECT non, pri FROM pwodwi ORDER BY pri ASC LIMIT 10 OFFSET 20;

INSERT INTO pwodwi (non, pri, stok) VALUES ('Savon', 150, 50);
UPDATE pwodwi SET pri = 175 WHERE id = 3;
DELETE FROM pwodwi WHERE id = 3;

SELECT COUNT(*) AS total_pwodwi FROM pwodwi;
SELECT SUM(montan) AS total_lavant FROM komand WHERE dat = '2026-10-18';
SELECT AVG(pri) AS pri_mwayen, MAX(pri) AS pi_che FROM pwodwi;

SELECT vil, COUNT(*) AS kantite FROM kliyan GROUP BY vil;
SELECT kategori, SUM(pri * kantite) AS lavant
FROM komand
GROUP BY kategori
HAVING lavant > 10000;

SELECT non, pri FROM pwodwi
WHERE pri > (SELECT AVG(pri) FROM pwodwi);

SELECT non FROM kliyan
WHERE id IN (SELECT id_kliyan FROM komand WHERE montan > 5000);

CREATE INDEX idx_komand_dat ON komand(dat);
EXPLAIN SELECT * FROM komand WHERE dat = '2026-10-18';
